#include "timbre_format.hpp"
#include <iostream>
int main(int argc,char** argv){try{if(argc<4||argc>5){std::cerr<<"Uso: lp_convert_timbre ORIGINAL PASTA_NOVA LIBSNDFILE [PASTA_SAMPLES]\n";return 2;}auto input=std::filesystem::u8path(argv[1]),output=std::filesystem::u8path(argv[2]),library=std::filesystem::u8path(argv[3]);lp::MetaSidecar meta;auto format=lp::detectarTimbreFormat(input);std::filesystem::path sfz;if(format==lp::TimbreFormat::NPNO)sfz=lp::npnoParaSFZ(input,output,meta,library,[](const std::string& s){std::cerr<<s<<'\n';});else if(format==lp::TimbreFormat::NSMP)sfz=lp::nsmpParaSFZ(input,output,meta,library);else if(format==lp::TimbreFormat::NKI)sfz=lp::nkiParaSFZ(input,output,meta,library,argc==5?std::filesystem::u8path(argv[4]):std::filesystem::path{});else throw std::runtime_error("Conversor destinado a NSMP/NSMP3/NSMP4 e NKI/npno; SFZ/SF2 seguem o importador existente");std::cout<<sfz.u8string()<<'\n';return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
